const body = $('Webhook').first().json.body || {};
if (!body.project_id) { const e = { valid: false, error: 'project_id obligatorio' }; return [{ json: e }]; }
if (!body.supplier_name || !body.supplier_email) { const e = { valid: false, error: 'supplier_name + supplier_email obligatorios' }; return [{ json: e }]; }
if (!body.scope_description) { const e = { valid: false, error: 'scope_description obligatorio' }; return [{ json: e }]; }
const out = {
  valid: true,
  project_id: body.project_id,
  trade_request_id: body.trade_request_id || null,
  trade_type: body.trade_type || null,
  supplier_name: body.supplier_name.toString().trim(),
  supplier_email: body.supplier_email.toString().trim().toLowerCase(),
  supplier_phone: body.supplier_phone || null,
  scope_description: body.scope_description.toString().slice(0, 4000),
  deadline_days: Number(body.deadline_days) || 7
};
return [{ json: out }];

