INSERT INTO trade_quotes (
  project_id, trade_request_id, trade_type,
  supplier_name, supplier_email, supplier_phone,
  request_sent_at, status, notes
) VALUES (
  $1::uuid, NULLIF($2,'')::uuid, $3,
  $4, $5, $6,
  now(), 'requested', $7
) RETURNING id, webhook_token;

