const inserted = $('Insert Quote').first().json;
const input = $('Validate').first().json;
const proj = $('Load Project').first().json.proj || {};

// === STUDIO PROFILE INJECTION (B25) ===
const _studio = $('Load Studio Profile').first().json || {};
function _safeStudio(v){ if(v==null)return null; if(typeof v==='string'){try{return JSON.parse(v);}catch(e){return v;}} return v; }
const _id = _safeStudio(_studio.identity) || {};
const _toneAll = _safeStudio(_studio.tone) || {};
const _toneProv = _toneAll.proveedores || _toneAll.clientes || {};
const nombreEstudio = _id.nombre_estudio || 'Estudio';
const persona = _id.persona_principal || 'Damian';
const tutea = _toneProv.tutea !== false; // default true (informal con oficios)
const formalidad = (_toneProv.formalidad || 'cercano').toLowerCase();
const esFormal = formalidad === 'formal' || formalidad === 'profesional';
// === END STUDIO PROFILE INJECTION ===

const saludo = esFormal ? ('Estimado/a ' + input.supplier_name + ':') : ('Hola ' + input.supplier_name + ',');
const verboSolic = tutea ? 'Te solicitamos' : 'Le solicitamos';
const contestaCTA = tutea ? 'contesta a este email con tu presupuesto' : 'conteste a este email con su presupuesto';
const recibirVerb = tutea ? 'recibamos tu respuesta' : 'recibamos su respuesta';
const preferirVerb = tutea ? 'Si prefieres' : 'Si prefiere';

const replyUrl = 'https://n8n-n8n.zzeluw.easypanel.host/webhook/trade-quote-reply?token=' + encodeURIComponent(inserted.webhook_token);
const html = '<h2>Solicitud de presupuesto — ' + (proj.project_name || 'proyecto') + '</h2>' +
  '<p>' + saludo + '</p>' +
  '<p>' + verboSolic + ' presupuesto para el siguiente trabajo del proyecto <b>' + (proj.project_name || '?') + '</b>' +
  (proj.location ? ' en ' + proj.location : '') +
  (proj.property_area ? ' (' + proj.property_area + ' m2)' : '') + ':</p>' +
  '<blockquote style="border-left:3px solid #2563eb;padding-left:12px;color:#374151">' + input.scope_description.replace(/\n/g, '<br>') + '</blockquote>' +
  '<p><b>Plazo de respuesta solicitado:</b> ' + input.deadline_days + ' días.</p>' +
  '<p>Para responder, ' + contestaCTA + '. Cuando ' + recibirVerb + ' la registraremos automáticamente. ' + preferirVerb + ' usar un formulario web, ' + (tutea ? 'puedes' : 'puede') + ' hacerlo aquí:</p>' +
  '<p><a href="' + replyUrl + '" style="background:#2563eb;color:white;padding:10px 20px;border-radius:4px;text-decoration:none">Enviar respuesta vía formulario</a></p>' +
  '<p style="color:#6b7280;font-size:12px">Reference quote ID: ' + inserted.id + '</p>' +
  '<p>Saludos,<br>' + persona + ' — ' + nombreEstudio + '</p>';
return [{ json: { html: html, supplier_email: input.supplier_email, supplier_name: input.supplier_name, project_name: proj.project_name, quote_id: inserted.id, webhook_token: inserted.webhook_token } }];
